func:
// Combines whichever topic just arrived into a running "latest" object,
// then re-applies the same threshold logic your ESP32 firmware used to run
// on-device. Manual overrides (set by the /command endpoint below) are
// respected the same way the firmware's manualOverride flags worked.

const topicKeyMap = {
  'irrigation/moisture': 'moisture',
  'irrigation/tank_level': 'tankLevel',
  'irrigation/ph': 'ph',
  'irrigation/temperature': 'temperature',
  'irrigation/humidity': 'humidity',
};

const key = topicKeyMap[msg.topic];
if (!key) return null;

let latest = flow.get('latest') || {};
latest[key] = Number(msg.payload);
flow.set('latest', latest);

// Wait until we have at least moisture and tank level before deciding anything
if (latest.moisture === undefined || latest.tankLevel === undefined) return null;

const overrides = flow.get('overrides') || { irrigation: false, fill: false };
const pumpState = flow.get('pumpState') || { irrigationPumpOn: false, tankFillPumpOn: false };

const MOISTURE_THRESHOLD = 30;
const TANK_LOW = 20;
const TANK_FULL = 95;

const commands = [];
const eventMessages = [];

if (!overrides.irrigation) {
  const shouldWater = latest.moisture < MOISTURE_THRESHOLD && latest.tankLevel > TANK_LOW;
  if (shouldWater !== pumpState.irrigationPumpOn) {
    pumpState.irrigationPumpOn = shouldWater;
    commands.push(shouldWater ? 'PUMP_ON' : 'PUMP_OFF');
    eventMessages.push(shouldWater
      ? 'Irrigation pump turned ON (soil below threshold)'
      : 'Irrigation pump turned OFF (moisture adequate)');
  }
}

if (!overrides.fill) {
  if (latest.tankLevel < TANK_LOW && !pumpState.tankFillPumpOn) {
    pumpState.tankFillPumpOn = true;
    commands.push('FILL_ON');
    eventMessages.push('Tank-fill pump turned ON (level below 20%)');
  } else if (latest.tankLevel > TANK_FULL && pumpState.tankFillPumpOn) {
    pumpState.tankFillPumpOn = false;
    commands.push('FILL_OFF');
    eventMessages.push('Tank-fill pump turned OFF (tank full)');
  }
}

flow.set('pumpState', pumpState);

const reading = {
  moisture: latest.moisture,
  tankLevel: latest.tankLevel,
  ph: latest.ph !== undefined ? latest.ph : 6.5,
  temperature: latest.temperature !== undefined ? latest.temperature : 25,
  humidity: latest.humidity !== undefined ? latest.humidity : 50,
  irrigationPumpOn: pumpState.irrigationPumpOn,
  tankFillPumpOn: pumpState.tankFillPumpOn,
};

const readingMsg = { payload: reading };
const commandMsgs = commands.length ? commands.map((c) => ({ payload: c })) : null;
const eventMsgs = eventMessages.length ? eventMessages.map((m) => ({ payload: { message: m } })) : null;

return [readingMsg, commandMsgs, eventMsgs];

// The backend calls this when the frontend's manual pump buttons are used.
// It sets/clears the same override flags the ESP32 firmware used to track
// locally, publishes the actual MQTT command to the ESP32, AND immediately
// pushes an updated reading to the backend — otherwise the dashboard would
// keep showing the old pump state until the next sensor tick arrives.

const command = (msg.payload && msg.payload.command) || '';
const overrides = flow.get('overrides') || { irrigation: false, fill: false };
const pumpState = flow.get('pumpState') || { irrigationPumpOn: false, tankFillPumpOn: false };
const latest = flow.get('latest') || {};

let mqttPayload = null;

switch (command) {
  case 'PUMP_ON':
    overrides.irrigation = true;
    pumpState.irrigationPumpOn = true;
    mqttPayload = 'PUMP_ON';
    break;
  case 'PUMP_OFF':
    overrides.irrigation = true;
    pumpState.irrigationPumpOn = false;
    mqttPayload = 'PUMP_OFF';
    break;
  case 'FILL_ON':
    overrides.fill = true;
    pumpState.tankFillPumpOn = true;
    mqttPayload = 'FILL_ON';
    break;
  case 'FILL_OFF':
    overrides.fill = true;
    pumpState.tankFillPumpOn = false;
    mqttPayload = 'FILL_OFF';
    break;
  case 'AUTO_MODE':
    overrides.irrigation = false;
    overrides.fill = false;
    mqttPayload = 'AUTO_MODE';
    break;
  default:
    mqttPayload = null;
}

flow.set('overrides', overrides);
flow.set('pumpState', pumpState);

// keep msg.req/msg.res intact so the http response node can reply
msg.payload = { ok: true };
const responseMsg = msg;
const cmdMsg = mqttPayload ? { payload: mqttPayload } : null;
const eventMsg = { payload: { message: `Manual override: ${command}` } };
const readingMsg = {
  payload: {
    moisture: latest.moisture !== undefined ? latest.moisture : 0,
    tankLevel: latest.tankLevel !== undefined ? latest.tankLevel : 0,
    ph: latest.ph !== undefined ? latest.ph : 6.5,
    temperature: latest.temperature !== undefined ? latest.temperature : 25,
    humidity: latest.humidity !== undefined ? latest.humidity : 50,
    irrigationPumpOn: pumpState.irrigationPumpOn,
    tankFillPumpOn: pumpState.tankFillPumpOn,
  },
};

return [responseMsg, cmdMsg, eventMsg, readingMsg];
